import re

_TAG = re.compile(r"<answer>\s*(\d{1,3})\s*</answer>")
_TAG_ANY = re.compile(r"<answer>.*?</answer>", re.S)
_NUM = re.compile(r"\d+")


def _reply_ok(reply):
    text = reply or ""
    if len(_NUM.findall(text)) != 1:
        return False
    tags = _TAG_ANY.findall(text)
    if len(tags) != 1:
        return False
    m = _TAG.fullmatch(tags[0])
    if m is None:
        return False
    n = int(m.group(1))
    return 1 <= n <= 40


def tighten(replies: list[str], state: dict, reward: float) -> float:
    if reward <= 0:
        return reward
    for r in replies:
        if not _reply_ok(r):
            return 0.0
    return reward
